insert into core.user_branch_access (id, organization_id, user_id, branch_id)
select core.generate_uuid_v7(), '00000000-0000-7000-8000-000000000001', u.id, b.id
from (values ('00000000-0000-7000-8000-000000000011'),
              ('00000000-0000-7000-8000-000000000012')) as staff(id)
cross join (values ('00000000-0000-7000-8000-000000000002'),
                   ('00000000-0000-7000-8000-000000000003')) as branches(id)
join core.users u on u.id = staff.id::uuid
join core.branches b on b.id = branches.id::uuid;

